function uuidv4() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    const v = c === "x" ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

// -------------------------
// Config / weights
// -------------------------
const WOMEN_KEYWORDS = [
  "women",
  "woman",
  "female",
  "ladies",
  "girls",
  "moms",
  "mothers",
  "motherhood",
  "prenatal",
  "pre-natal",
  "postnatal",
  "post-natal",
  "pre/postnatal",
  "child care",
  "pregnancy",
  "beauty",
  "salon",
  "makeup",
  "bridal",
  "women's health",
  "women empowerment",
  "women 40+",
  "sisterhood",
  "mentoring ministry for women",
  "she",
];

const MEN_KEYWORDS = [
  "men",
  "man",
  "male",
  "gentlemen",
  "boys",
  "dads",
  "fathers",
  "barber",
  "grooming for men",
  "men's health",
  "bro",
  "gym bros",
  "he",
];

const INDUSTRY_SYNONYMS = {
  law: ["legal", "attorney", "paralegal"],
  sports: ["fitness", "athletics", "coaching", "training"],
  events: ["event planning", "weddings", "conferences", "ceremonies"],
  beauty: ["salon", "makeup", "cosmetics", "skincare"],
  health: ["wellness", "mental health", "nutrition"],
  tech: ["software", "saas", "technology", "it"],
  marketing: ["advertising", "branding", "promotion"],
};

const TOOL_SYNONYMS = {
  "google workspace": ["gsuite", "g suite", "google suite"],
  "google sheets": ["sheets", "g sheets", "google spreadsheets"],
  "google docs": ["docs", "g docs"],
  "microsoft excel": ["excel", "ms excel"],
  "microsoft office": ["ms office", "office 365", "o365", "m365", "microsoft 365"],
  "canva": ["canva design"],
  "figma": ["figma design"],
};




// -------------------------
// Utility
// -------------------------
function toStr(x) {
  return x === null || x === undefined ? "" : String(x);
}

function cleanCommaSet(strVal) {
  if (!strVal) return new Set();
  return new Set(
    toStr(strVal)
      .split(",")
      .map(s => s.trim().toLowerCase())
      .filter(Boolean)
  );
}

function cleanIndustries(strVal) {
  if (!strVal) return new Set();
  const s = toStr(strVal).replace(/[\/;]/g, ",");
  return new Set(
    s.split(",")
      .map(x => x.trim().toLowerCase())
      .filter(Boolean)
  );
}

function expandIndustries(setIn) {
  const expanded = new Set(setIn);

  for (const [key, syns] of Object.entries(INDUSTRY_SYNONYMS)) {
    if (expanded.has(key)) syns.forEach(s => expanded.add(s));

    for (const syn of syns) {
      if (expanded.has(syn)) {
        expanded.add(key);
        syns.forEach(s => expanded.add(s));
      }
    }
  }

  return expanded;
}

function normalizeTool(s) {
  return toStr(s)
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function cleanToolsSet(strVal) {
  if (!strVal) return new Set();
  const s = toStr(strVal).replace(/[\/;\n]/g, ",");
  const raw = s
    .split(",")
    .map(x => normalizeTool(x))
    .filter(Boolean);

  const set = new Set(raw);

  for (const [canon, syns] of Object.entries(TOOL_SYNONYMS)) {
    const canonN = normalizeTool(canon);
    const synN = syns.map(normalizeTool);

    if (set.has(canonN)) synN.forEach(v => set.add(v));
    for (const v of synN) {
      if (set.has(v)) set.add(canonN);
    }
  }

  return set;
}

function toolsMatchScore(founderToolsSet, doerToolsSet) {
  if (!founderToolsSet || founderToolsSet.size === 0) return 100;

  let matches = 0;
  for (const ft of founderToolsSet) {
    // direct hit
    if (doerToolsSet.has(ft)) { matches++; continue; }

    // fuzzy containment fallback. handles "google sheets" vs "sheets"
    let hit = false;
    for (const dt of doerToolsSet) {
      if (ft.length >= 4 && (dt.includes(ft) || ft.includes(dt))) { hit = true; break; }
    }
    if (hit) matches++;
  }

  if (matches === founderToolsSet.size) return 100;
  if (matches > 0) return 50;
  return 0;
}



function parseScore(val) {
  if (val === null || val === undefined) return 0;
  let s = toStr(val).trim();
  s = s.replace("%", "");
  if (!s || s === "-") return 0;
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

function hasAny(text, keywords) {
  const t = toStr(text).toLowerCase();
  if (!t) return false;
  return keywords.some(k => t.includes(k));
}

function prefersFemale(text) {
  return hasAny(text, WOMEN_KEYWORDS);
}

function prefersMale(text) {
  return hasAny(text, MEN_KEYWORDS);
}

function normalizePronouns(p) {
  return toStr(p).toLowerCase().replace(/[^a-z]/g, "");
}

function isMalePronouns(p) {
  const s = normalizePronouns(p);
  return (s.includes("he") || s.includes("him") || s.includes("his")) && !s.includes("she") && !s.includes("her");
}

function isFemalePronouns(p) {
  const s = normalizePronouns(p);
  return (s.includes("she") || s.includes("her")) && !s.includes("he") && !s.includes("him") && !s.includes("his");
}

function eligibleByGender(founderOverview, pronouns) {
  const femaleSignal = prefersFemale(founderOverview);
  const maleSignal = prefersMale(founderOverview);

  // If both signals exist, founder does not prefer gender
  if (femaleSignal && maleSignal) return true;

  if (femaleSignal && isMalePronouns(pronouns)) return false;
  if (maleSignal && isFemalePronouns(pronouns)) return false;

  return true;
}

// Basic token overlap similarity (no external libs)
function simpleTextSim(a, b) {
  const ta = toStr(a).toLowerCase().match(/[a-z0-9]+/g) || [];
  const tb = toStr(b).toLowerCase().match(/[a-z0-9]+/g) || [];
  if (!ta.length || !tb.length) return 0;

  const fa = new Map();
  const fb = new Map();

  for (const w of ta) fa.set(w, (fa.get(w) || 0) + 1);
  for (const w of tb) fb.set(w, (fb.get(w) || 0) + 1);

  let dot = 0, na = 0, nb = 0;

  for (const [w, c] of fa.entries()) {
    na += c * c;
    const cb = fb.get(w) || 0;
    dot += c * cb;
  }

  for (const c of fb.values()) nb += c * c;

  const denom = Math.sqrt(na) * Math.sqrt(nb);
  return denom ? dot / denom : 0;
}

// Very small fuzzy fallback
function roughStringSimilarity(a, b) {
  a = toStr(a).toLowerCase();
  b = toStr(b).toLowerCase();

  if (!a || !b) return 0;
  if (a === b) return 1;

  let best = 0;

  for (let i = 0; i < a.length; i++) {
    for (let j = i + 1; j <= a.length; j++) {
      const sub = a.slice(i, j);
      if (sub.length < 3) continue;
      if (b.includes(sub)) best = Math.max(best, sub.length);
    }
  }

  const avg = (a.length + b.length) / 2;
  return avg ? best / avg : 0;
}

// Lead score P1..P15
function leadPriorityRank(val) {
  const s = toStr(val).trim().toLowerCase();
  const m = s.match(/\bp\s*([0-9]{1,2})\b/);
  if (!m) return 9999;

  const rank = parseInt(m[1], 10);
  if (rank >= 1 && rank <= 15) return rank;

  return 9999;
}




function extractRelevantTestCols(founderTaskExp) {
  const map = [
    { key: "marketing design", col: "Task/Output Experience - Blueprint Test Scores - Marketing Design" },
    { key: "marketing funnels", col: "Task/Output Experience - Blueprint Test Scores - Marketing Funnels" },
    { key: "email marketing", col: "Task/Output Experience - Blueprint Test Scores - Email Marketing" },
    { key: "social media", col: "Task/Output Experience - Blueprint Test Scores - Social Media" },
    { key: "virtual assistant", col: "Task/Output Experience - Blueprint Test Scores - Virtual Assistant Foundations" },
    { key: "administration", col: "Task/Output Experience - Blueprint Test Scores - Administration Support" },
  ];

  const s = toStr(founderTaskExp).toLowerCase();
  return map.filter(x => s.includes(x.key)).map(x => x.col);
}

const topCandidatesByFounder = new Map(); // fk -> array of candidates

function pushTopCandidate(fk, cand, K = 5) {
  const arr = topCandidatesByFounder.get(fk) || [];
  arr.push(cand);
  arr.sort((a, b) => b.score - a.score);
  if (arr.length > K) arr.length = K;
  topCandidatesByFounder.set(fk, arr);
}

function buildAlternativesForFounder(fk, matchedDoerId, limit = 2) {
    const list = topCandidatesByFounder.get(fk) || [];
    const seen = new Set();
    const out = [];

    for (const c of list) {
      const cid = toStr(c.doer_id || c.doer_name);
      if (!cid) continue;
      if (matchedDoerId && cid === toStr(matchedDoerId)) continue;
      if (seen.has(cid)) continue;

      const rr = generateRationale(c.scores || {});
      out.push({
        doer_id: c.doer_id || null,
        "DOER NAME": c.doer_name || null,
        "Doer Type": c.doer_type || null,
        "Matching Score": c.score || 0,
        ...(c.scores || {}),
        "Rationale": rr.rationale,
        "Trade-offs": rr.tradeoffs,
      });

      seen.add(cid);
      if (out.length >= limit) break;
    }

    return out;
  }


// -------------------------
// Scoring
// -------------------------

function taskOutputMatchScore(doer, relevantCols) {
  if (!relevantCols || relevantCols.length === 0) return 0;

  let mx = 0;
  let has = false;

  for (const col of relevantCols) {
    if (doer[col] !== undefined) {
      has = true;
      mx = Math.max(mx, parseScore(doer[col]));
    }
  }

  if (!has) return 0;
  if (mx >= 70) return 100;
  if (mx >= 40) return 50;

  return 0;
}

function industryMatchScore(founderIndSet, doerPrevSet, doerOpenSet) {
  if (!founderIndSet || founderIndSet.size === 0) return 100;

  const fExp = expandIndustries(founderIndSet);
  const dUnion = new Set([...doerPrevSet, ...doerOpenSet]);
  const dExp = expandIndustries(dUnion);

  for (const f of fExp) if (dExp.has(f)) return 100;

  for (const f of fExp) {
    for (const d of dExp) {
      if (roughStringSimilarity(f, d) > 0.75) return 100;
    }
  }

  return 0;
}

function educationMatchScore(founderOverview, doerEduWork) {
  const sim = simpleTextSim(founderOverview, doerEduWork);
  if (sim >= 0.5) return 100;
  if (sim >= 0.2) return 50;
  return 0;

  //const o = toStr(founderOverview).toLowerCase();
  //const e = toStr(doerEduWork).toLowerCase();
 // if (!o || !e) return 0;
  //return e.includes(o) ? 100 : 0;
}

function workExperienceMatchScore(founderOverview, doerEduWork) {
    const sim = simpleTextSim(founderOverview, doerEduWork);
  if (sim >= 0.5) return 100;
  if (sim >= 0.2) return 50;
  return 0;

 // const o = toStr(founderOverview).toLowerCase();
  //const w = toStr(doerEduWork).toLowerCase();
 // if (!o || !w) return 0;
 // return w.includes(o) ? 100 : 0;
}

function genderPreferenceScore(founderOverview, pronouns) {
  const o = toStr(founderOverview).toLowerCase();
  const p = toStr(pronouns).toLowerCase();
  if (!o || !p) return 0;

  const womenHit = WOMEN_KEYWORDS.some(k => o.includes(k));
  const menHit = MEN_KEYWORDS.some(k => o.includes(k));

  // If both, no preference
  if (womenHit && menHit) return 0;

  if (womenHit) {
    const female = (p.includes("she") || p.includes("her")) && !p.includes("he");
    const male = (p.includes("he") || p.includes("him") || p.includes("his")) && !p.includes("she");
    if (female) return 10;
    if (male) return -10;
    return 0;
  }

  if (menHit) {
    const male = (p.includes("he") || p.includes("him") || p.includes("his")) && !p.includes("she");
    const female = (p.includes("she") || p.includes("her")) && !p.includes("he");
    if (male) return 10;
    if (female) return -10;
    return 0;
  }

  return 0;
}

function geniusZoneScore(founderOverview, doerGenius) {
  const sim = simpleTextSim(founderOverview, doerGenius);
  if (sim >= 0.5) return 100;
  if (sim >= 0.2) return 50;
  return 0;
}

function finalWeightedScore(t, x, i, e, w, g, gz) {
  return t * 0.25 + x * 0.25 + i * 0.15 + e * 0.15 + w * 0.10 + g * 0.10 + gz * 0.10;
}

function generateRationale(scores) {
  const r = [];
  const t = [];

  if (scores["Tools Score"] === 100) r.push("Doer fully matches required tools.");
  else if (scores["Tools Score"] === 50) {
    r.push("Partial tool match.");
    t.push("Some tools missing.");
  } else t.push("No tool experience matched.");

  if (scores["Task Score"] === 100) r.push("Strong task blueprint scores.");
  else if (scores["Task Score"] === 50) {
    r.push("Moderate blueprint scores.");
    t.push("May need task support.");
  } else t.push("No relevant task experience.");

  if (scores["Industry Score"] === 100) r.push("Aligned industry experience.");
  else t.push("No matching industry background.");

  if (scores["Gender Score"] === 10) r.push("Gender aligns with audience.");
  else if (scores["Gender Score"] === -10) t.push("Potential gender mismatch.");

  if (scores["Genius Zone Score"] === 100) r.push("Genius Zone highly aligned.");
  else if (scores["Genius Zone Score"] === 50) r.push("Some Genius Zone relevance.");
  else t.push("No match in Genius Zone.");

  return { rationale: r.join("; "), tradeoffs: t.join("; ") };
}

function computeSubscores(founder, doer) {
  const fTools = cleanToolsSet(founder["Tools Experience Required"]);
  const fTaskCols = extractRelevantTestCols(founder["Task/Output experience: Blueprint"]);
  const fInds = cleanIndustries(founder["Business Industry Experience"]);
  const fOverview = toStr(founder["Business Overview"]);

  const dTools = cleanToolsSet(doer["Doer Tools Experience"]);
  const dPrev = cleanIndustries(doer["Previous Business Industry Experience"]);
  const dOpen = cleanIndustries(doer["Open to the following Business Industry Experience"]);
  const dEdu = toStr(doer["Educational Background and Work Experience"]);
  const pronouns = toStr(doer["Which pronouns would you like us to use to address you?"]);
  const genius = toStr(doer["Doer Genius Zone"] || doer["Task/Output experience - Doer Self Assessment - Genius Zone"] || "");

  const t = toolsMatchScore(fTools, dTools);
  const x = taskOutputMatchScore(doer, fTaskCols);
  const i = industryMatchScore(fInds, dPrev, dOpen);
  const e = educationMatchScore(fOverview, dEdu);
  const w = workExperienceMatchScore(fOverview, dEdu);
  const g = genderPreferenceScore(fOverview, pronouns);
  const gz = geniusZoneScore(fOverview, genius);
  const final = finalWeightedScore(t, x, i, e, w, g, gz);

  return {
    "Tools Score": t,
    "Task Score": x,
    "Industry Score": i,
    "Education Score": e,
    "Work Score": w,
    "Gender Score": g,
    "Genius Zone Score": gz,
    "Final Score": final,
  };
}


const inputItem = $input.first().json;
const founders = Array.isArray(inputItem.founders) ? inputItem.founders : [];
const doers = Array.isArray(inputItem.doers) ? inputItem.doers : [];
const run_id = inputItem.run_id || uuidv4();

// Sort founders by Lead score P1..P15
const sortedFounders = [...founders]
  .map(f => ({ ...f, __priority: leadPriorityRank(f["Lead score"]) }))
  .sort((a, b) => a.__priority - b.__priority);

// Split doers by tenure
const tenured = doers.filter(d => toStr(d["Doer Type"]).toLowerCase() === "tenured");
const newbies = doers.filter(d => toStr(d["Doer Type"]).toLowerCase() === "newbie");

// Assignment maps
const assignedDoerByFounder = new Map();
const assignedFounderByDoer = new Map();
const detailsByPair = new Map(); // key: founderId|doerId

function keyPair(fn, dn) {
  return `${fn}||${dn}`;
}

function founderKey(f) {
  return toStr(f.founder_id || f["Founder Name"]);
}

function doerKey(d) {
  return toStr(d.doer_id || d["DOER NAME"]);
}

function assign(founder, doer, scores) {
  const fk = founderKey(founder);
  const dk = doerKey(doer);
  assignedDoerByFounder.set(fk, dk);
  assignedFounderByDoer.set(dk, fk);
  detailsByPair.set(keyPair(fk, dk), scores);
}

function founderIsFree(founder) {
  return !assignedDoerByFounder.has(founderKey(founder));
}

function doerIsFree(doer) {
  return !assignedFounderByDoer.has(doerKey(doer));
}

function precomputeEdges(candidates) {
  const edges = [];

  for (const f of sortedFounders) {
    const fOverview = toStr(f["Business Overview"]);

    for (const d of candidates) {
      const pron = toStr(d["Which pronouns would you like us to use to address you?"]);
      if (!eligibleByGender(fOverview, pron)) continue;

      const scores = computeSubscores(f, d);
      const score = scores["Final Score"];

      pushTopCandidate(founderKey(f), {
        doer_id: d.doer_id || null,
        doer_name: d["DOER NAME"] || null,
        doer_type: d["Doer Type"] || null,
        score: Math.round(score * 100) / 100,
        scores,
      }, 5);

      edges.push({
        founder: f,
        doer: d,
        score,
        scores,
      });
    }
  }

  return edges;
}

// Phase A1: greedy best edges among tenured
const tenuredEdges = precomputeEdges(tenured).sort((a, b) => b.score - a.score);
for (const e of tenuredEdges) {
  if (founderIsFree(e.founder) && doerIsFree(e.doer)) {
    assign(e.founder, e.doer, e.scores);
  }
}

// Phase B: fill remaining founders with best newbie edges
const newbieEdges = precomputeEdges(newbies).sort((a, b) => b.score - a.score);
for (const e of newbieEdges) {
  if (founderIsFree(e.founder) && doerIsFree(e.doer)) {
    assign(e.founder, e.doer, e.scores);
  }
}

// Build output results per founder in sorted order
const results = [];

for (const f of sortedFounders) {
  const fk = founderKey(f);
  const assignedDoerId = assignedDoerByFounder.get(fk);

if (!assignedDoerId) {
  const emptyScores = {
    "Tools Score": 0,
    "Task Score": 0,
    "Industry Score": 0,
    "Education Score": 0,
    "Work Score": 0,
    "Gender Score": 0,
    "Genius Zone Score": 0,
    "Final Score": 0,
  };

  results.push({
    run_id,
    founder_id: f.founder_id || null,
    doer_id: null,
    "Founder Name": f["Founder Name"],
    "Matched Doer": null,
    "Matching Score": 0,
    ...emptyScores,
    "Rationale": "No eligible doer under gender filter or no available candidates.",
    "Trade-offs": "No eligible doer under gender filter or no available candidates.",

    ai_summary_input: {
      founder: {
        id: f.founder_id || null,
        lead_score: f["Lead score"] || null,
        business_overview: f["Business Overview"] || null,
        tools_required: f["Tools Experience Required"] || null,
        task_blueprint: f["Task/Output experience: Blueprint"] || null,
        industries: f["Business Industry Experience"] || null,
      },
      doer: null,
      scores: emptyScores,
      rationale: "No eligible doer under gender filter or no available candidates.",
      tradeoffs: "No eligible doer under gender filter or no available candidates.",
    },
  });

  continue;
}


  const doerObj = doers.find(d => doerKey(d) === assignedDoerId);
  const scores = detailsByPair.get(keyPair(fk, assignedDoerId)) || {};
  const rationaleObj = generateRationale(scores);

  const matchedKey = doerObj ? (doerObj.doer_id || doerObj["DOER NAME"]) : assignedDoerId;
  const alts = buildAlternativesForFounder(fk, matchedKey, 2);

  results.push({
    run_id,
    founder_id: f.founder_id || null,
    doer_id: doerObj ? (doerObj.doer_id || null) : null,
    "Founder Name": f["Founder Name"],
    "Matched Doer": doerObj ? doerObj["DOER NAME"] : assignedDoerId,
    "Matching Score": Math.round((scores["Final Score"] || 0) * 100) / 100,
    ...scores,
    "Rationale": rationaleObj.rationale,
    "Trade-offs": rationaleObj.tradeoffs,
    "Alternative 1": alts[0] || null,
    "Alternative 2": alts[1] || null,

          ai_summary_input: {
        founder: {
          id: f.founder_id || null,
          lead_score: f["Lead score"] || null,
          business_overview: f["Business Overview"] || null,
          tools_required: f["Tools Experience Required"] || null,
          task_blueprint: f["Task/Output experience: Blueprint"] || null,
          industries: f["Business Industry Experience"] || null,
        },
        doer: doerObj ? {
          id: doerObj.doer_id || null,
          name: doerObj["DOER NAME"] || null,
          doer_type: doerObj["Doer Type"] || null,
          pronouns: doerObj["Which pronouns would you like us to use to address you?"] || null,
          tools: doerObj["Doer Tools Experience"] || null,
          industries_prev: doerObj["Previous Business Industry Experience"] || null,
          industries_open: doerObj["Open to the following Business Industry Experience"] || null,
          edu_work: doerObj["Educational Background and Work Experience"] || null,
          genius_zone: doerObj["Doer Genius Zone"] || doerObj["Task/Output experience - Doer Self Assessment - Genius Zone"] || null,
        } : null,
        scores: scores,
        rationale: rationaleObj.rationale,
        tradeoffs: rationaleObj.tradeoffs,
      },
  });
}

// -------------------------
// NEW. Unmatched lists
// -------------------------
const matchedFounderKeys = new Set(
  results.filter(r => r["Matched Doer"]).map(r => toStr(r.founder_id || r["Founder Name"]))
);

const matchedDoerKeys = new Set(
  results.filter(r => r["Matched Doer"]).map(r => toStr(r.doer_id || r["Matched Doer"]))
);

// Unmatched founders (those with no matched doer)
const unmatched_founders = results
  .filter(r => !r["Matched Doer"])
  .map(r => ({
    run_id,
    founder_id: r.founder_id || null,
    "Founder Name": r["Founder Name"] || null,
    reason: r["Rationale"] || "No eligible doer under gender filter or no available candidates.",
    "Alternative 1": r["Alternative 1"] || null,
    "Alternative 2": r["Alternative 2"] || null,
  }));

// Unmatched doers (doers not assigned to any founder)
const unmatched_doers = doers
  .filter(d => !assignedFounderByDoer.has(doerKey(d)))
  .map(d => ({
    run_id,
    doer_id: d.doer_id || null,
    "DOER NAME": d["DOER NAME"] || null,
    "Doer Type": d["Doer Type"] || null,
    reason: "Not selected. Either lower score than selected doers, filtered out by gender, or not needed.",
  }));

// Keep your previous tenured_unmatched too (optional)
const tenured_unmatched = tenured
  .filter(d => !assignedFounderByDoer.has(doerKey(d)))
  .map(d => ({
    run_id,
    doer_id: d.doer_id || null,
    "DOER NAME": d["DOER NAME"],
    reason: "Unmatched: either ineligible (gender filter) or insufficient founders.",
  }));




return [
  {
    json: {
      run_id,
      results,
      unmatched_founders,
      unmatched_doers,
      tenured_unmatched,
      stats: {
        founders_total: founders.length,
        doers_total: doers.length,
