        summary: null,
        factors: [],
        risks: [],
        next_steps: [],
      },

      alternatives: {
        alt1: alt1Match
          ? {
              match: alt1Match,
              ai: { summary: null, factors: [], risks: [], next_steps: [] },
            }
          : null,
        alt2: alt2Match
          ? {
              match: alt2Match,
              ai: { summary: null, factors: [], risks: [], next_steps: [] },
            }
          : null,
      },
    };
  }


  const ai = parsed.value || {};
  const alt1AI = normalizeAltBlock(ai.alt1);
  const alt2AI = normalizeAltBlock(ai.alt2);

  return {
    run_id,
    match_bucket,

    founder: {
      founder_id: pick(founder.id ?? row.founder_id),
      founder_name: pick(row["Founder Name"] ?? row["Founder name"] ?? row.founder_name),
      priority_score: pick(founder.lead_score ?? row["Lead score"]),
      type: pick(founder.type),
      contract: pick(founder.contract),
      category: pick(founder.category),
      business_overview: pick(founder.business_overview),
      tools_required: pick(founder.tools_required),
      task_blueprint: pick(founder.task_blueprint),
      industries: pick(founder.industries),
    },

    doer: doer
      ? {
          doer_id: pick(doer.id ?? row.doer_id),
          doer_name: pick(doer.name ?? row["Matched Doer"]),
          doer_type: pick(doer.doer_type ?? row["Doer Category"]),
