          proud_moment: pick(doer.proud_moment),
          priority: pick(doer.doer_priority)

        }
      : null,

    scores: {
      tools_score: pick(row["Tools Score"]),
      task_score: pick(row["Task Score"]),
      industry_score: pick(row["Industry Score"]),
      education_score: pick(row["Education Score"]),
      work_score: pick(row["Work Score"]),
      gender_score: pick(row["Gender Score"]),
      genius_zone_score: pick(row["Genius Zone Score"]),
