    },

    rationale: pick(row["Rationale"]),
    tradeoffs: pick(row["Trade-offs"]),
    backups: pick(row["Backup Doers"]),

    ai: {
      status,
      error: null,
      summary: ai.summary ?? null,
      factors: normalizeFactors(ai.factors),
      risks: normalizeArrayStrings(ai.risks),
      next_steps: normalizeArrayStrings(ai.next_steps),
    },

    alternatives: {
      alt1: alt1Match
        ? {
            match: alt1Match,
            ai: {
              summary: alt1AI.summary,
              factors: alt1AI.factors,
              risks: alt1AI.risks,
