// Helpers
// -------------------------
function toStr(x) {
  return x === null || x === undefined ? "" : String(x);
}

function normCat(x) {
  return toStr(x).trim().toUpperCase();
}

function normShift(x) {
  const s = normCat(x);
  if (s === "FT") return "FT";
  if (s === "PT") return "PT";
  return s;
}

function getFounderShiftType(founder) {

  return normShift(founder["founder_shift_type"]);
}

function getDoerShiftType(doer) {

  return normShift(doer["doer_shift_type"]);
}


function getFounderType(founder) {
  return normCat(founder["Type"]);
}


function getDoerCategory(doer) {
  return normCat(doer["Doer Category"]);
}



function cleanIndustries(strVal) {
  if (!strVal) return new Set();
  const s = toStr(strVal).replace(/[\/;]/g, ",");
  return new Set(
    s.split(",").map((x) => x.trim().toLowerCase()).filter(Boolean)
  );
}

function expandIndustries(setIn) {
  const expanded = new Set(setIn);
  for (const [key, syns] of Object.entries(INDUSTRY_SYNONYMS)) {
    if (expanded.has(key)) syns.forEach((s) => expanded.add(s));
    for (const syn of syns) {
      if (expanded.has(syn)) {
        expanded.add(key);
        syns.forEach((s) => expanded.add(s));
      }
    }
  }
  return expanded;
}

function normalizeTool(s) {
  return toStr(s)
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function shiftMatches(founder, doer) {
  return getFounderShiftType(founder) === getDoerShiftType(doer);
}


function doerPriorityRank(doer) {
  const p = getDoerPriority(doer);

  if (p === "P1") return 1;
  if (p === "P2") return 2;
  if (p === "P3") return 3;
  if (p === "P4") return 4;
  if (p === "P5") return 5;
  if (p === "P6") return 6;

  return 999;
}

function compareCandidates(a, b) {
  const pa = doerPriorityRank(a.doer);
  const pb = doerPriorityRank(b.doer);

  // priority first
  if (pa !== pb) return pa - pb;

  // then match score
  return b.score - a.score;
}


function cleanToolsSet(strVal) {
  if (!strVal) return new Set();
  const s = toStr(strVal).replace(/[\/;\n]/g, ",");
  const raw = s.split(",").map((x) => normalizeTool(x)).filter(Boolean);

  const set = new Set(raw);

  for (const [canon, syns] of Object.entries(TOOL_SYNONYMS)) {
    const canonN = normalizeTool(canon);
    const synN = syns.map(normalizeTool);

    if (set.has(canonN)) synN.forEach((v) => set.add(v));
    for (const v of synN) if (set.has(v)) set.add(canonN);
  }
  return set;
}

function toolsMatchScore(founderToolsSet, doerToolsSet) {
  if (!founderToolsSet || founderToolsSet.size === 0) return 100;

  let matches = 0;

  for (const ft of founderToolsSet) {
    if (doerToolsSet.has(ft)) {
      matches++;
      continue;
    }

    let hit = false;
    for (const dt of doerToolsSet) {
      if (ft.length >= 4 && (dt.includes(ft) || ft.includes(dt))) {
        hit = true;
        break;
      }
    }
    if (hit) matches++;
  }

  if (matches === founderToolsSet.size) return 100;
  if (matches > 0) return 50;
  return 0;
}

function parseScore(val) {
  if (val === null || val === undefined) return 0;
  let s = toStr(val).trim().replace("%", "");
  if (!s || s === "-") return 0;
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

function hasAny(text, keywords) {
  const t = toStr(text).toLowerCase();
  if (!t) return false;
  return keywords.some((k) => t.includes(k));
}

function prefersFemale(text) { return hasAny(text, WOMEN_KEYWORDS); }
function prefersMale(text) { return hasAny(text, MEN_KEYWORDS); }

function normalizePronouns(p) {
  return toStr(p).toLowerCase().replace(/[^a-z]/g, "");
}

function isMalePronouns(p) {
  const s = normalizePronouns(p);
  return (s.includes("he") || s.includes("him") || s.includes("his"))
    ? !s.includes("she") && !s.includes("her")
    : false;
}

function isFemalePronouns(p) {
  const s = normalizePronouns(p);
  return (s.includes("she") || s.includes("her"))
    ? !s.includes("he") && !s.includes("him") && !s.includes("his")
    : false;
}

function eligibleByGender(founderOverview, pronouns) {
  const femaleSignal = prefersFemale(founderOverview);
  const maleSignal = prefersMale(founderOverview);

  if (femaleSignal && maleSignal) return true;
  if (femaleSignal && isMalePronouns(pronouns)) return false;
  if (maleSignal && isFemalePronouns(pronouns)) return false;

  return true;
}

function getDoerPriority(doer) {
  const p = toStr(doer["doer_priority"]).trim().toUpperCase();
  if (!p) return "P3";
  return p;
}

function isVipFounder(founder) {
  const pr = leadPriorityRank(founder["Lead score"]);
  return pr >= 1 && pr <= 6;
}

function doerAllowedForFounder(founder, doer) {
  const dp = getDoerPriority(doer);

  // only P1 to P6 are valid buckets
  if (!["P1", "P2", "P3", "P4", "P5", "P6"].includes(dp)) return false;

  // P1 doers are reserved for all VIP founders
  if (dp === "P1" && !isVipFounder(founder)) return false;

  return true;
}

// Similarity
function simpleTextSim(a, b) {
  const ta = toStr(a).toLowerCase().match(/[a-z0-9]+/g) || [];
  const tb = toStr(b).toLowerCase().match(/[a-z0-9]+/g) || [];
  if (!ta.length || !tb.length) return 0;

  const fa = new Map();
  const fb = new Map();
  for (const w of ta) fa.set(w, (fa.get(w) || 0) + 1);
  for (const w of tb) fb.set(w, (fb.get(w) || 0) + 1);

  let dot = 0, na = 0, nb = 0;

  for (const [w, c] of fa.entries()) {
    na += c * c;
    dot += c * (fb.get(w) || 0);
  }
  for (const c of fb.values()) nb += c * c;

  const denom = Math.sqrt(na) * Math.sqrt(nb);
  return denom ? dot / denom : 0;
}

function roughStringSimilarity(a, b) {
  a = toStr(a).toLowerCase();
  b = toStr(b).toLowerCase();
  if (!a || !b) return 0;
  if (a === b) return 1;

  let best = 0;
  for (let i = 0; i < a.length; i++) {
    for (let j = i + 1; j <= a.length; j++) {
      const sub = a.slice(i, j);
      if (sub.length < 3) continue;
      if (b.includes(sub)) best = Math.max(best, sub.length);
    }
  }
  const avg = (a.length + b.length) / 2;
  return avg ? best / avg : 0;
}

function leadPriorityRank(val) {
  const s = toStr(val).trim().toLowerCase();
  const m = s.match(/\bp\s*([0-9]{1,2})\b/);
  if (!m) return 9999;
  const rank = parseInt(m[1], 10);
  return rank >= 1 && rank <= 15 ? rank : 9999;
}

function extractRelevantTestCols(founderTaskExp) {
  const map = [
    { key: "marketing design", col: "Task/Output Experience - Blueprint Test Scores - Marketing Design" },
    { key: "marketing funnels", col: "Task/Output Experience - Blueprint Test Scores - Marketing Funnels" },
    { key: "email marketing", col: "Task/Output Experience - Blueprint Test Scores - Email Marketing" },
    { key: "social media", col: "Task/Output Experience - Blueprint Test Scores - Social Media" },
    { key: "virtual assistant", col: "Task/Output Experience - Blueprint Test Scores - Virtual Assistant Foundations" },
    { key: "administration", col: "Task/Output Experience - Blueprint Test Scores - Administration Support" },
  ];
  const s = toStr(founderTaskExp).toLowerCase();
  return map.filter((x) => s.includes(x.key)).map((x) => x.col);
}


// Alternatives
// -------------------------
const topCandidatesByFounder = new Map();

function pushTopCandidate(fk, cand, K = 5) {
  const arr = topCandidatesByFounder.get(fk) || [];
  arr.push(cand);
  arr.sort((a, b) => b.score - a.score);
  if (arr.length > K) arr.length = K;
  topCandidatesByFounder.set(fk, arr);
}

function buildAlternativesForFounder(fk, matchedDoerId, limit = 2) {
  const list = topCandidatesByFounder.get(fk) || [];
  const seen = new Set();
  const out = [];

  for (const c of list) {
    const cid = toStr(c.doer_id || c.doer_name);
    if (!cid) continue;
    if (matchedDoerId && cid === toStr(matchedDoerId)) continue;
    if (seen.has(cid)) continue;

    const rr = generateRationale(c.scores || {});
    out.push({
      doer_id: c.doer_id || null,
      "DOER NAME": c.doer_name || null,
      "Doer Tenure": c.doer_type || null,
      "Doer Type": c.doer_category || null,
      "Matching Score": c.score || 0,
      ...(c.scores || {}),
      Rationale: rr.rationale,
      "Trade-offs": rr.tradeoffs,
    });

    seen.add(cid);
    if (out.length >= limit) break;
  }

  return out;
}


// Scoring
// -------------------------
function taskOutputMatchScore(doer, relevantCols) {
  if (!relevantCols || relevantCols.length === 0) return 0;
  let mx = 0;
  let has = false;
  for (const col of relevantCols) {
    if (doer[col] !== undefined) {
      has = true;
      mx = Math.max(mx, parseScore(doer[col]));
    }
  }
  if (!has) return 0;
  if (mx >= 70) return 100;
  if (mx >= 40) return 50;
  return 0;
}

function industryMatchScore(founderIndSet, doerPrevSet, doerOpenSet) {
  if (!founderIndSet || founderIndSet.size === 0) return 100;

  const fExp = expandIndustries(founderIndSet);
  const dUnion = new Set([...doerPrevSet, ...doerOpenSet]);
  const dExp = expandIndustries(dUnion);

  for (const f of fExp) if (dExp.has(f)) return 100;

  for (const f of fExp) {
    for (const d of dExp) {
      if (roughStringSimilarity(f, d) > 0.75) return 100;
    }
  }
  return 0;
}

function educationMatchScore(founderOverview, doerEduWork) {
  const sim = simpleTextSim(founderOverview, doerEduWork);
  if (sim >= 0.5) return 100;
  if (sim >= 0.2) return 50;
  return 0;
}

function workExperienceMatchScore(founderOverview, doerEduWork) {
  const sim = simpleTextSim(founderOverview, doerEduWork);
  if (sim >= 0.5) return 100;
  if (sim >= 0.2) return 50;
  return 0;
}

function genderPreferenceScore(founderOverview, pronouns) {
  const o = toStr(founderOverview).toLowerCase();
  const p = toStr(pronouns).toLowerCase();
  if (!o || !p) return 0;

  const womenHit = WOMEN_KEYWORDS.some((k) => o.includes(k));
  const menHit = MEN_KEYWORDS.some((k) => o.includes(k));
  if (womenHit && menHit) return 0;

  if (womenHit) {
    const female = (p.includes("she") || p.includes("her")) && !p.includes("he");
    const male = (p.includes("he") || p.includes("him") || p.includes("his")) && !p.includes("she");
    if (female) return 100;
    if (male) return -100;
    return 0;
  }

  if (menHit) {
    const male = (p.includes("he") || p.includes("him") || p.includes("his")) && !p.includes("she");
    const female = (p.includes("she") || p.includes("her")) && !p.includes("he");
    if (male) return 100;
    if (female) return -100;
    return 0;
  }

  return 0;
}

function geniusZoneScore(founderOverview, doerGenius) {
  const sim = simpleTextSim(founderOverview, doerGenius);
  if (sim >= 0.5) return 100;
  if (sim >= 0.2) return 50;
  return 0;
}

function finalWeightedScore(t, x, i, e, w, g, gz) {
  return t * 0.25 + x * 0.25 + i * 0.15 + e * 0.15 + w * 0.1 + gz * 0.1;
}

function generateRationale(scores) {
  const r = [];
  const t = [];

  if (scores["Tools Score"] === 100) r.push("Doer fully matches required tools.");
  else if (scores["Tools Score"] === 50) { r.push("Partial tool match."); t.push("Some tools missing."); }
  else t.push("No tool experience matched.");

  if (scores["Task Score"] === 100) r.push("Strong task blueprint scores.");
  else if (scores["Task Score"] === 50) { r.push("Moderate blueprint scores."); t.push("May need task support."); }
  else t.push("No relevant task experience.");

  if (scores["Industry Score"] === 100) r.push("Aligned industry experience.");
  else t.push("No matching industry background.");

  if (scores["Gender Score"] === 10) r.push("Gender aligns with audience.");
  else if (scores["Gender Score"] === -10) t.push("Potential gender mismatch.");

  if (scores["Genius Zone Score"] === 100) r.push("Genius Zone highly aligned.");
  else if (scores["Genius Zone Score"] === 50) r.push("Some Genius Zone relevance.");
  else t.push("No match in Genius Zone.");

  return { rationale: r.join("; "), tradeoffs: t.join("; ") };
}

function computeSubscores(founder, doer) {
  const fTools = cleanToolsSet(founder["Tools Experience Required"]);
  const fTaskCols = extractRelevantTestCols(founder["Task/Output experience: Blueprint"]);
  const fInds = cleanIndustries(founder["Business Industry Experience"]);
  const fOverview = toStr(founder["Business Overview"]);

  const dTools = cleanToolsSet(doer["Doer Tools Experience"]);
  const dPrev = cleanIndustries(doer["Previous Business Industry Experience"]);
  const dHob = toStr(doer["Hobbies"]);
  const dProud = toStr(doer["Proud Moment"]);
  const dOpen = cleanIndustries(doer["Open To Industry"]);
  const dEdu = toStr(doer["Educational Background and Work Experience"]);
  const pronouns = toStr(doer["Pronoun"]);
  const genius = toStr(
    doer["Doer Genius Zone"] ||
      doer["Task/Output experience - Doer Self Assessment - Genius Zone"] ||
      ""
  );

  const t = toolsMatchScore(fTools, dTools);
  const x = taskOutputMatchScore(doer, fTaskCols + ',' + fOverview);
  const i = industryMatchScore(fInds, dPrev, dOpen + ',' + dHob + ',' + dEdu + ',' + genius);
  const e = educationMatchScore(fOverview, dEdu);
  const w = workExperienceMatchScore(fOverview,  dEdu + ',' + dPrev + ',' + dProud);
  const g = genderPreferenceScore(fOverview, pronouns);
  const gz = geniusZoneScore(fOverview + fTaskCols, genius + ',' + dProud);
  const baseFinal = finalWeightedScore(t, x, i, e, w, g, gz);
  const gBonus = g * 0.5;
  const final =  baseFinal + gBonus;


  return {
    "Tools Score": t,
    "Task Score": x,
    "Industry Score": i,
    "Education Score": e,
    "Work Score": w,
    "Gender Score": g,
    "Genius Zone Score": gz,
    "Final Score": final,
  };
}


// Matching input
// -------------------------
const inputItem = $input.first().json;
const founders = Array.isArray(inputItem.founders) ? inputItem.founders : [];
const doers = Array.isArray(inputItem.doers) ? inputItem.doers : [];
const run_id = inputItem.run_id || uuidv4();

// Sort by Priority
const sortedFounders = [...founders]
  .map((f) => ({ ...f, __priority: leadPriorityRank(f["Priority Level"]) }))
  .sort((a, b) => a.__priority - b.__priority);

// Keys
function founderKey(f) { return toStr(f.founder_id || f["Founder Name"]); }
function doerKey(d) { return toStr(d.doer_id || d["DOER NAME"]); }

// Tenure split
function isTenured(d) { return toStr(d["Doer Type"]).toLowerCase() === "tenured"; }
function isNewbie(d) { return toStr(d["Doer Type"]).toLowerCase() === "newbie"; }

const tenuredDoers = doers.filter(isTenured);
const newbieDoers = doers.filter(isNewbie);

const p1TenuredDoers = doers.filter(d => getDoerPriority(d) === "P1" && isTenured(d));

// Assignment maps (primary match)
const assignedDoerByFounder = new Map();
const assignedFounderByDoer = new Map();
const detailsByPair = new Map();
function keyPair(fn, dn) { return `${fn}||${dn}`; }

function assignPrimary(founder, doer, scores) {
  const fk = founderKey(founder);
  const dk = doerKey(doer);
  assignedDoerByFounder.set(fk, dk);
  assignedFounderByDoer.set(dk, fk);
  detailsByPair.set(keyPair(fk, dk), scores);
}
function doerIsFreePrimary(doer) { return !assignedFounderByDoer.has(doerKey(doer)); }


// Build per-founder candidate lists (category restricted) for PRIMARY match
// -------------------------
const p1TenuredByFounder = new Map();
const p1NewbieByFounder = new Map();
const generalTenuredByFounder = new Map();
const generalNewbieByFounder = new Map();

function addCandidate(map, fk, cand) {
  const arr = map.get(fk) || [];
  arr.push(cand);
  map.set(fk, arr);
}

function getDoerPriority(doer) {
  const p = toStr(doer["doer_priority"]).trim().toUpperCase();
  if (!p) return "P3";
  return p;
}

const generalTenuredDoers = doers.filter(d => {
  const dp = getDoerPriority(d);
  return ["P2", "P3", "P4", "P5", "P6"].includes(dp) && isTenured(d);
});

const generalNewbieDoers = doers.filter(d => {
  const dp = getDoerPriority(d);
  return ["P2", "P3", "P4", "P5", "P6"].includes(dp) && isNewbie(d);
});

for (const f of sortedFounders) {
  const fk = founderKey(f);
  const fOverview = toStr(f["Business Overview"]);
  const fType = getFounderType(f);

  const pools = [
    { doers: p1TenuredDoers, map: p1TenuredByFounder },
    { doers: generalTenuredDoers, map: generalTenuredByFounder },
    { doers: generalNewbieDoers, map: generalNewbieByFounder },
  ];

  for (const pool of pools) {
    for (const d of pool.doers) {
      if (getDoerCategory(d) !== fType) continue;
      if (!shiftMatches(f, d)) continue;
      if (!doerAllowedForFounder(f, d)) continue;

      const pron = toStr(d["Pronoun"]);
      if (!eligibleByGender(fOverview, pron)) continue;

      const scores = computeSubscores(f, d);
      const score = scores["Final Score"];

      addCandidate(pool.map, fk, {
        founder: f,
        doer: d,
        score,
        scores,
      });

      pushTopCandidate(fk, {
        doer_id: d.doer_id || null,
        doer_name: d["DOER NAME"] || null,
        doer_type: d["Doer Type"] || null,
        doer_category: d["Doer Category"] || null,
        score: Math.round(score * 100) / 100,
        scores,
      }, 5);
    }
  }
}


for (const [fk, arr] of p1TenuredByFounder.entries()) arr.sort((a, b) => b.score - a.score);
for (const [fk, arr] of generalTenuredByFounder.entries()) arr.sort((a, b) => b.score - a.score);
for (const [fk, arr] of generalNewbieByFounder.entries()) arr.sort((a, b) => b.score - a.score);


// PRIMARY assignment 
// -------------------------
for (const f of sortedFounders) {
  const fk = founderKey(f);
  if (assignedDoerByFounder.has(fk)) continue;

  let picked = null;
  const vip = isVipFounder(f);

  const orderedLists = vip
    ? [
        p1TenuredByFounder.get(fk) || [],
        generalTenuredByFounder.get(fk) || [],
        generalNewbieByFounder.get(fk) || [],
      ]
    : [
        generalTenuredByFounder.get(fk) || [],
        generalNewbieByFounder.get(fk) || [],
      ];

  for (const list of orderedLists) {
    for (const c of list) {
      if (doerIsFreePrimary(c.doer)) {
        picked = c;
        break;
      }
    }
    if (picked) break;
  }

  if (picked) assignPrimary(picked.founder, picked.doer, picked.scores);
}


// BACKUP assignment
// -------------------------
function isTwelveMonths(contractVal) {
  const s = toStr(contractVal).toLowerCase().trim();
  if (!s) return false;
  // accepts: "12 months", "12 month", "12", "12mos", etc
  if (/\b12\b/.test(s) && s.includes("month")) return true;
  if (s === "12") return true;
  if (s.includes("12mo") || s.includes("12 mos")) return true;
  if (s.includes("12 months")) return true;
  return false;
}

function backupQuotaByContract(founder) {
  const contract = founder["Contract"] || founder["contract"] || "";
  return isTwelveMonths(contract) ? 2 : 1;
}

function backupObj(d, score, scores) {
  if (!d) return null;
  return {
    doer_id: d.doer_id || null,
    "DOER NAME": d["DOER NAME"] || null,
    "Doer Tenure": d["Doer Type"] || null,
    "Doer Category": d["Doer Category"] || null,
    "Matching Score": Math.round((score || 0) * 100) / 100,
    ...(scores || {}),
  };
}

//remaining doer pool
const remainingDoers = doers
  .filter((d) => !assignedFounderByDoer.has(doerKey(d)))
  .slice();


const backupAssignedDoerKeys = new Set();

function doerIsFreeBackup(d) {
  const dk = doerKey(d);
  if (!dk) return false;
  if (assignedFounderByDoer.has(dk)) return false; // primary used
  if (backupAssignedDoerKeys.has(dk)) return false; // backup already used
  return true;
}

function pickBestBackupForFounder(founder) {
  const fType = getFounderType(founder);
  const fOverview = toStr(founder["Business Overview"]);
  let best = null;

  for (const d of remainingDoers) {
    if (!doerIsFreeBackup(d)) continue;
    if (getDoerCategory(d) !== fType) continue;

    const pron = toStr(d["Pronoun"]);
    if (!eligibleByGender(fOverview, pron)) continue;

    const scores = computeSubscores(founder, d);
    const score = scores["Final Score"];

    if (!best || score > best.score) best = { doer: d, score, scores };
  }

  return best;
}

const backupsByFounder = new Map();

for (const f of sortedFounders) {
  const fk = founderKey(f);
  const need = backupQuotaByContract(f);

  const chosen = [];
  for (let i = 0; i < need; i++) {
    const best = pickBestBackupForFounder(f);
    if (!best) break;

    backupAssignedDoerKeys.add(doerKey(best.doer));
    chosen.push(backupObj(best.doer, best.score, best.scores));
  }

  backupsByFounder.set(fk, chosen);
}


// Build output results
// -------------------------
const results = [];

for (const f of sortedFounders) {
  const fk = founderKey(f);
  const assignedDoerId = assignedDoerByFounder.get(fk);

  const backupsArr = backupsByFounder.get(fk) || [];
  const b1 = backupsArr[0] || null;
  const b2 = backupsArr[1] || null;

  if (!assignedDoerId) {
    const emptyScores = {
      "Tools Score": 0,
      "Task Score": 0,
      "Industry Score": 0,
      "Education Score": 0,
      "Work Score": 0,
      "Gender Score": 0,
      "Genius Zone Score": 0,
      "Final Score": 0,
    };

    results.push({
      run_id,
      match_id: run_id + "_" + (f.founder_id || fk),
      founder_id: f.founder_id || null,
      doer_id: null,
      "Founder Name": f["Founder Name"],
      "Type (Founder)": f["Type"] || null,

      "Matched Doer": null,
      "Type (Doer)": null,
      "Matching Score": 0,

      ...emptyScores,

      Rationale: "No eligible doer under category and gender filter or no available candidates.",
      "Trade-offs": "No eligible doer under category and gender filter or no available candidates.",

      "Alternative 1": null,
      "Alternative 2": null,

      "Backup Doers": backupsArr,
      "Backup Doer 1": b1,
      "Backup Doer 2": b2,

      ai_summary_input: {
        founder: {
          id: f.founder_id || null,
          lead_score: f["Priority Level"] || null,
          business_overview: f["Business Overview"] || null,
          tools_required: f["Tools Experience Required"] || null,
          task_blueprint: f["Task/Output experience: Blueprint"] || null,
          industries: f["Business Industry Experience"] || null,
          type: f["Type"] || null,
          contract: f["Contract"] || null,
          category: f["Category"] || null,
        },
        doer: null,
        scores: emptyScores,
        rationale: "No eligible doer under category and gender filter or no available candidates.",
        tradeoffs: "No eligible doer under category and gender filter or no available candidates.",
        backups: backupsArr,
      },
    });

    continue;
  }

  const doerObj = doers.find((d) => doerKey(d) === assignedDoerId);
  const scores = detailsByPair.get(keyPair(fk, assignedDoerId)) || {};
  const rationaleObj = generateRationale(scores);

  const matchedKey = doerObj ? doerKey(doerObj) : assignedDoerId;
  const alts = buildAlternativesForFounder(fk, matchedKey, 2);

  results.push({
    run_id,
    match_id: run_id + "_" + (f.founder_id || fk),
    founder_id: f.founder_id || null,
    doer_id: doerObj ? doerObj.doer_id || null : null,

    "Founder Name": f["Founder Name"],
    "Type (Founder)": f["Type"] || null,


    "Matched Doer": doerObj ? doerObj["DOER NAME"] : assignedDoerId,
    "Type (Doer)": doerObj ? doerObj["Doer Category"] || null : null,

    "Matching Score": Math.round((scores["Final Score"] || 0) * 100) / 100,
    ...scores,

    Rationale: rationaleObj.rationale,
    "Trade-offs": rationaleObj.tradeoffs,

    "Alternative 1": alts[0] || null,
    "Alternative 2": alts[1] || null,

    "Backup Doers": backupsArr,
    "Backup Doer 1": b1,
    "Backup Doer 2": b2,

    ai_summary_input: {
      founder: {
        id: f.founder_id || null,
        lead_score: f["Priority Level"] || null,
        business_overview: f["Business Overview"] || null,
        tools_required: f["Tools Experience Required"] || null,
        task_blueprint: f["Task/Output experience: Blueprint"] || null,
        industries: f["Business Industry Experience"] || null,
        type: f["Type"] || null,
        contract: f["Contract"] || null,
        category: f["Category"] || null,
      },
      doer: doerObj
        ? {
            id: doerObj.doer_id || null,
            name: doerObj["DOER NAME"] || null,
            doer_type: doerObj["Doer Category"] || null,
            doer_tenure: doerObj["Doer Type"] || null,
            pronouns: doerObj["Pronoun"] || null,
            tools: doerObj["Doer Tools Experience"] || null,
            industries_prev: doerObj["Previous Business Industry Experience"] || null,
            industries_open: doerObj["Open To Industry"] || null,
            edu_work: doerObj["Educational Background and Work Experience"] || null,
            genius_zone:
              doerObj["Doer Genius Zone"] ||
              doerObj["Task/Output experience - Doer Self Assessment - Genius Zone"] ||
              null,
            hobbies: doerObj["Hobbies"] || null,
            proud_moment: doerObj["Proud Moment"] || null,
            doer_priority: doerObj["doer_priority"] || null
          }
        : null,
      scores,
      rationale: rationaleObj.rationale,
      tradeoffs: rationaleObj.tradeoffs,
      backups: backupsArr,
    },
  });
}


// Unmatched lists
// -------------------------
const unmatched_founders = results
  .filter((r) => !r["Matched Doer"])
  .map((r) => ({
    run_id,
    founder_id: r.founder_id || null,
    "Founder Name": r["Founder Name"] || null,
    reason: r.Rationale || "No eligible doer under category and gender filter or no available candidates.",
  }));

const unmatched_doers = doers
  .filter((d) => !assignedFounderByDoer.has(doerKey(d)) && !backupAssignedDoerKeys.has(doerKey(d)))
  .map((d) => ({
    run_id,
    doer_id: d.doer_id || null,
    "DOER NAME": d["DOER NAME"] || null,
    "Doer Tenure": d["Doer Type"] || null,
    "Doer Type": d["Doer Category"] || null,
    reason: "Not selected. Either lower score than selected doers, filtered out, or not needed.",
  }));

const tenured_unmatched = doers
  .filter((d) => isTenured(d) && !assignedFounderByDoer.has(doerKey(d)) && !backupAssignedDoerKeys.has(doerKey(d)))
  .map((d) => ({
    run_id,
    doer_id: d.doer_id || null,
    "DOER NAME": d["DOER NAME"],
    "Doer Category": d["Doer Category"] || null,
    reason: "Unmatched: either filtered out or insufficient founders.",
  }));

return [
  {
    json: {
      run_id,
      results,
      unmatched_founders,
      unmatched_doers,
      tenured_unmatched,
      stats: {
        founders_total: founders.length,
        doers_total: doers.length,
        matched_total: results.filter((r) => r["Matched Doer"]).length,
        unmatched_founders_total: unmatched_founders.length,
        unmatched_doers_total: unmatched_doers.length,
        tenured_unmatched_total: tenured_unmatched.length,
        backup_used_total: backupAssignedDoerKeys.size,
      },
    },
  },
];
